package APIcalls;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

public class modelAdapter {

    private static final String OLLAMA_URL = "http://localhost:11434/api/generate";
    private static final String MODEL_NAME = "cas/teuken-7b-q4km:latest";
    private final HttpClient client;

    public modelAdapter() {
        this.client = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(10))
                .build();
    }

    /**
     * Sendet einen Prompt an Ollama und gibt die Text-Antwort zurück
     */
    public String generate(String prompt) throws Exception {

        String jsonBody = """
        {
          "model": "%s",
          "prompt": "%s",
          "stream": false
        }
        """.formatted(MODEL_NAME, escapeJson(prompt));

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(OLLAMA_URL))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(jsonBody))
                .build();

        HttpResponse<String> response =
                client.send(request, HttpResponse.BodyHandlers.ofString());

        return extractResponse(response.body());
    }

    /**
     * Extrahiert das "response"-Feld aus der JSON-Antwort
     * (minimalistisch, ohne externe Bibliotheken)
     */
    private String extractResponse(String json) {
        int start = json.indexOf("\"response\":\"");
        if (start == -1) return json;

        start += 12;
        int end = json.indexOf("\"", start);

        return json.substring(start, end)
                .replace("\\n", "\n")
                .replace("\\\"", "\"");
    }

    /**
     * Verhindert kaputtes JSON bei Sonderzeichen
     */
    private String escapeJson(String text) {
        return text
                .replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\n", "\\n");
    }
}
